        soleApprover: j['sole_approver'] as bool,
        stepId: j['step_id'] as String,
        stepName: j['step_name'] as String,
        stepUp: j['step_up'],
        subject: j['subject'],
        timeoutAt: j['timeout_at'],
        workflow: j['workflow'] as String,
      );

  Map<String, dynamic> toJson() => {
